scripts:
(() => {
  const plans = [
    { name: 'Starter', conv: 250, domains: 1, month: 25, year: 240 / 12, why: '~250 conversations · 1 domain' },
    { name: 'Growth', conv: 1250, domains: 5, month: 69, year: 662 / 12, why: '~1,250 conversations · 5 domains' },
    { name: 'Pro', conv: 5000, domains: 10, month: 149, year: 1430 / 12, why: '~5,000 conversations · 10 domains' },
  ];
  const $ = (id) => document.getElementById(id);
  const fmt = (n) => Math.round(n).toLocaleString('en-US');
  const money = (n) => '$' + fmt(n);
  // Slider 0–100 maps to 100–200,000 visitors on a log scale
  const visitsFrom = (v) => { const x = Math.round(100 * Math.pow(2000, v / 100)); return x < 1000 ? Math.round(x / 50) * 50 : x < 20000 ? Math.round(x / 500) * 500 : Math.round(x / 5000) * 5000; };
  const billing = $('billing');
  let last = '';
  const calc = () => {
    const visits = visitsFrom(+$('visits').value);
    const rate = +$('rate').value / 100, leadRate = +$('lead').value / 100;
    const value = Math.max(1, +$('value').value || 1);
    const domains = +$('domains').value;
    const per = billing.dataset.value || 'year';
    $('visits-out').textContent = fmt(visits);
    $('rate-out').textContent = $('rate').value + '%';
    $('lead-out').textContent = $('lead').value + '%';
    $('domains-out').textContent = domains >= 12 ? '12+' : domains;
    const conv = visits * rate;
    const plan = plans.find((p) => conv <= p.conv && domains <= p.domains);
    const leads = conv * leadRate;
    if (!plan) {
      $('plan-name').textContent = 'Enterprise';
      $('plan-why').textContent = 'Over 5,000 conversations or 10 domains';
      $('r-cost').textContent = 'Custom';
      $('r-be').textContent = '—';
      $('r-verdict').textContent = 'Talk to SiteMind sales for a custom quote.';
      $('plan-cta').textContent = 'Explore SiteMind ↗';
    } else {
      const cost = plan[per];
      const be = Math.ceil(cost / value);
      $('plan-name').textContent = plan.name;
      $('plan-why').textContent = plan.why;
      $('r-cost').textContent = money(cost);
      $('r-be').textContent = fmt(be) + (be === 1 ? ' lead' : ' leads');
      $('r-verdict').textContent = leads >= be
        ? `Your estimate (${fmt(leads)} leads) covers the cost. Confirm it with the free trial.`
        : `Your estimate (${fmt(leads)} leads) is below break-even. Grow traffic first, or test with the trial.`;
      $('plan-cta').textContent = `Try ${plan.name} free for 3 days ↗`;
    }
    $('r-conv').textContent = fmt(conv);
    $('r-leads').textContent = fmt(leads);
    $('r-val').textContent = money(leads * value);
    const name = plan ? plan.name : 'Enterprise';
    document.querySelectorAll('#plan-cards .plan-card').forEach((c) => c.classList.toggle('is-pick', c.dataset.plan === name));
    if (name !== last) { window.fgBump?.($('plan-name')); last = name; }
  };
  ['visits', 'rate', 'lead', 'value', 'domains'].forEach((id) => $(id).addEventListener('input', calc));
  billing.addEventListener('change', calc);
  calc();
})();
